"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[9635],{25515:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"PerkEffectsDispatcher","desc":"The single writer of the perk buff folders. Personal buffs go to\\n`ReplicatedStorage/PerkBuffs/<UserId>` (per-player attributes); party buffs go\\nto `ReplicatedStorage/PartyPerkBuffs` as the per-perk MAX level across all\\nplayers in the server (the \\"only highest active\\" rule), plus the holder\'s\\nUserId as `<BuffKey>HolderId` (0 = none). Recomputes on\\nallocate/respec (`Signals.OnPerkStateChanged`), player join, and player leave.\\nBridges the Junk Rarity party perk onto the existing `ApplyTierMultiplier`\\nsignal (which `JunkService` already listens for).","realm":["Server"],"source":{"line":15,"path":"src/ServerScriptService/PerkEffectsDispatcher.server.luau"}}')}}]);